const BY_KEY = new Map(HEXAGRAM_SEO_REGISTRY.map((entry) => [String(entry.locale) + ":" + String(entry.number), entry]));

export function hexagramSeoFor(number: number, locale: ContentLocale): HexagramSeoEntry {
  const entry = BY_KEY.get(String(locale) + ":" + String(number));
  if (!entry) throw new Error("HEXAGRAM_SEO_ENTRY_MISSING: locale=" + locale + " number=" + number);
  return entry;
}

export function hexagramSeoRows(): readonly HexagramSeoEntry[] {
  return HEXAGRAM_SEO_REGISTRY;
}
